    for u in text:gmatch("file:%s*'([^']+)'") do add(u) end
    for u in text:gmatch('"file"%s*:%s*"([^"]+)"') do add(u) end
    for u in text:gmatch([[https?://[^"'%s<>\\]+%.m3u8[^"'%s<>\\]*]]) do add(u) end
    for u in text:gmatch([[https?://[^"'%s<>\\]+%.mp4[^"'%s<>\\]*]]) do add(u) end
